const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const taskId = clean(input.task_id);

if (!taskId) {
  throw new Error('task_id es obligatorio');
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(taskId)) {
  throw new Error(
    `task_id no es un UUID válido: ${taskId}`
  );
}

return [
  {
    json: {
      task_id: taskId,

      update: {
        status: 'completed',
        completed_at: new Date().toISOString()
      }
    }
  }
];

const task = $json.data;

if (!task?.id) {
  throw new Error(
    'Directus no devolvió task.id'
  );
}

if (task.status !== 'completed') {
  throw new Error(
    `Estado inesperado tras completar tarea: ${task.status}`
  );
}

if (!task.completed_at) {
  throw new Error(
    'Directus no devolvió completed_at'
  );
}

return [
  {
    json: {
      status: 'completed',
      task
    }
  }
];
